    /**
     * Tests creating a new Lead.
     *
     * @return    Lead
     */
    public Lead testCreate() throws Throwable {
    Lead entity = null;

    LOGGER.info( "LeadTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a Lead");

    StringBuilder msg = new StringBuilder( "-- Failed to create a Lead" );

    try {
        entity = service.createLead( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getLeadId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a Lead with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

    /**
     * Tests reading a Lead.
     *
     * @return    Lead
     */
    public Lead testRead() throws Throwable {
    LOGGER.info( "LeadTest:testRead()" );
    LOGGER.info( "-- Reading a previously created Lead" );

    Lead entity = null;
    StringBuilder msg = new StringBuilder( "-- Failed to read Lead with primary key" );
    msg.append( theId );

    try {
        entity = service.getLead( new LeadFetchOneSummary(theId) );

        assertNotNull( entity,msg.toString() );

        // for use later
        theId = entity.getLeadId();

        LOGGER.info( "-- Successfully found Lead " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests updating a Lead.
     *
     * @return    Lead
     */
    public Lead testUpdate() throws Throwable {
    LOGGER.info( "LeadTest:testUpdate()" );
    LOGGER.info( "-- Attempting to update a Lead." );

    StringBuilder msg = new StringBuilder( "Failed to update a Lead : " );
    Lead entity = null;

    try {
        UpdateLeadCommand updateCommand = this.generateUpdateCommand();

        // apply the current id as to update the fields of the current entity
        updateCommand.setLeadId( theId );

        assertNotNull( updateCommand, msg.toString() );

        LOGGER.info( "-- Now updating the created Lead." );

        entity = service.updateLead( updateCommand );

        assertNotNull( entity, msg.toString()  );

        LOGGER.info( "-- Successfully saved Lead - " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : primarykey-" + theId + " : entity-" +  entity + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests deleting a Lead.
     */
    public void testDelete() throws Throwable {
    LOGGER.info( "LeadTest:testDelete()" );
    LOGGER.info( "-- Deleting a previously created Lead." );

    try {
        DeleteLeadCommand deleteCommand = new DeleteLeadCommand( theId );

        service.delete( deleteCommand );

        LOGGER.info( "-- Successfully deleted Lead with primary key " + theId );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( "-- Failed to delete Lead with primary key " + theId );

        throw e;
    }
}

    /**
     * Tests getting all Leads.
     *
     * @return    Collection
     */
    public List<Lead> testGetAll() throws Throwable {
    LOGGER.info( "LeadTest:testGetAll() - Retrieving Collection of Leads:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Lead : " );
    List<Lead> collection  = null;

    try {
        // call the static get method on the LeadService
        collection = service.getAllLead();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Lead currEntity  = null;
            Iterator<Lead> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getLeadId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

